// A reattachable tab: enough to re-`open_session` after a frontend reload. The
// tmux session (and the agent inside) survives in the Rust backend; only the
// xterm wiring is lost on reload, so we replay these on boot.
export interface OpenTab {
  name: string;
  // Boop can identify a pane as `%123`; keep that attach target separate from
  // the stable tab identity and title.
  tmuxTarget?: string;
  command: string | null;
  cwd: string | null;
  graphics?: boolean; // kitty-graphics (awrit) tab — restore the overlay on reload
  // Opened by a strip row to WATCH someone else's lane (DockStripPanel's
  // bridge), never launched by the user here. Closing it must leave the lane
  // running. Lifetime = this openTabs row: persisted, so it survives a reload
.paint-caption-enabled.on { opacity: 1; color: #1f8a3b; }
.paint-caption-style { min-width: 26px; min-height: 22px; padding: 0 4px; font-weight: 700; opacity: 0.55; }
.paint-caption-style.on { opacity: 1; color: var(--panel-fg, #111); background: var(--row-active-bg, #b8d6ff); }
.paint-caption-error { color: #c0392b; max-width: 300px; overflow-wrap: anywhere; }

/* Marbler is embedded inside a dock panel. Its standalone demo stylesheet also
   declares page-shell dimensions; these rules bind those dimensions to the
   Instant panel and leave the document shell under Instant's ownership. */
html body { min-width: 0; }
.boop-network-panel { min-height: 0; }
.boop-marbler { display: flex; min-height: 0; flex: 1; overflow: hidden; }
.boop-marbler > .app-shell {
  width: 100%;
  height: 100%;
  min-width: 0;
  margin: 0;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
.boop-marbler .network-panel { min-height: 0; }
.boop-marbler .grid-scroller { min-height: 0; }



